const CDN = "https://sempertex.com/cdn/shop/articles/";

export function fuenteIdea(slug: string): FuenteIdea | null {
  const fila = IDEAS[slug];
  if (!fila) return null;
  const [numero, titulo, foto, etiquetas, productos] = fila;
  return {
    numero, titulo, fotoUrl: foto.startsWith("https://") ? foto : CDN + foto, etiquetas: [...etiquetas],
    productos: productos.flatMap((i) => { const p = PRODUCTOS[i]; return p ? [{ nombre: p[0], url: `/products/${p[1]}` }] : []; }),
  };
}

export const SLUGS_IDEAS: readonly string[] = Object.keys(IDEAS);
